import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.CNXp-E7Q.js";const u=JSON.parse('{"title":"Command-Line Help for bupha","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),d={name:"reference/cli.md"};function h(l,e,i,c,s,n){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="command-line-help-for-bupha" tabindex="-1">Command-Line Help for <code>bupha</code> <a class="header-anchor" href="#command-line-help-for-bupha" aria-label="Permalink to &quot;Command-Line Help for `bupha`&quot;">​</a></h1><p>This document contains the help content for the <code>bupha</code> command-line program.</p><p><strong>Command Overview:</strong></p><ul><li><a href="#bupha"><code>bupha</code>↴</a></li><li><a href="#bupha-watch"><code>bupha watch</code>↴</a></li><li><a href="#bupha-init"><code>bupha init</code>↴</a></li><li><a href="#bupha-doctor"><code>bupha doctor</code>↴</a></li><li><a href="#bupha-run"><code>bupha run</code>↴</a></li><li><a href="#bupha-deploy"><code>bupha deploy</code>↴</a></li><li><a href="#bupha-deploy-service"><code>bupha deploy service</code>↴</a></li><li><a href="#bupha-deploy-webhook"><code>bupha deploy webhook</code>↴</a></li><li><a href="#bupha-deploy-env"><code>bupha deploy env</code>↴</a></li><li><a href="#bupha-deploy-check"><code>bupha deploy check</code>↴</a></li><li><a href="#bupha-deploy-release"><code>bupha deploy release</code>↴</a></li><li><a href="#bupha-destroy"><code>bupha destroy</code>↴</a></li><li><a href="#bupha-destroy-service"><code>bupha destroy service</code>↴</a></li><li><a href="#bupha-destroy-webhook"><code>bupha destroy webhook</code>↴</a></li><li><a href="#bupha-destroy-worktrees"><code>bupha destroy worktrees</code>↴</a></li></ul><h2 id="bupha" tabindex="-1"><code>bupha</code> <a class="header-anchor" href="#bupha" aria-label="Permalink to &quot;`bupha`&quot;">​</a></h2><p>the oxpecker on your repo&#39;s back — headless CI</p><p><strong>Usage:</strong> <code>bupha [OPTIONS] &lt;COMMAND&gt;</code></p><h6 id="subcommands" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>watch</code> — Serve the webhook → queue → runner loop</li><li><code>init</code> — Scaffold CI in a repo (dagger module install or script skeleton)</li><li><code>doctor</code> — Check what the loaded config actually needs on this box</li><li><code>run</code> — Run the pipeline locally (the runner&#39;s invocation, current dir)</li><li><code>deploy</code> — Install-time helpers — no files to copy by hand</li><li><code>destroy</code> — Teardown counterparts of <code>deploy</code></li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--config &lt;CONFIG&gt;</code> — Path to bupha.toml (default: ./bupha.toml or ~/.config/bupha/)</li></ul><h2 id="bupha-watch" tabindex="-1"><code>bupha watch</code> <a class="header-anchor" href="#bupha-watch" aria-label="Permalink to &quot;`bupha watch`&quot;">​</a></h2><p>Serve the webhook → queue → runner loop</p><p><strong>Usage:</strong> <code>bupha watch</code></p><h2 id="bupha-init" tabindex="-1"><code>bupha init</code> <a class="header-anchor" href="#bupha-init" aria-label="Permalink to &quot;`bupha init`&quot;">​</a></h2><p>Scaffold CI in a repo (dagger module install or script skeleton)</p><p><strong>Usage:</strong> <code>bupha init [DIR]</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><p><code>&lt;DIR&gt;</code> — Repo dir to initialize (default: cwd)</p><p>Default value: <code>.</code></p></li></ul><h2 id="bupha-doctor" tabindex="-1"><code>bupha doctor</code> <a class="header-anchor" href="#bupha-doctor" aria-label="Permalink to &quot;`bupha doctor`&quot;">​</a></h2><p>Check what the loaded config actually needs on this box</p><p><strong>Usage:</strong> <code>bupha doctor</code></p><h2 id="bupha-run" tabindex="-1"><code>bupha run</code> <a class="header-anchor" href="#bupha-run" aria-label="Permalink to &quot;`bupha run`&quot;">​</a></h2><p>Run the pipeline locally (the runner&#39;s invocation, current dir)</p><p><strong>Usage:</strong> <code>bupha run [FUNCTION]</code></p><h6 id="arguments-1" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-1" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;FUNCTION&gt;</code> — Function for the dagger runner (default: from config)</li></ul><h2 id="bupha-deploy" tabindex="-1"><code>bupha deploy</code> <a class="header-anchor" href="#bupha-deploy" aria-label="Permalink to &quot;`bupha deploy`&quot;">​</a></h2><p>Install-time helpers — no files to copy by hand</p><p><strong>Usage:</strong> <code>bupha deploy &lt;COMMAND&gt;</code></p><h6 id="subcommands-1" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-1" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>service</code> — Write + enable the systemd user unit (needs enable-linger for boot persistence)</li><li><code>webhook</code> — Register/update the repo&#39;s push webhook via <code>gh api</code></li><li><code>env</code> — Seed ~/.config/bupha/env with the secret names</li><li><code>check</code> — Verify the whole install: unit, secrets, hook, endpoint, token</li><li><code>release</code> — One-time seed: cargo publish in dep order + tag {repo}-v{ver}. Explicit — publishing is the irreversible step in the flow</li></ul><h2 id="bupha-deploy-service" tabindex="-1"><code>bupha deploy service</code> <a class="header-anchor" href="#bupha-deploy-service" aria-label="Permalink to &quot;`bupha deploy service`&quot;">​</a></h2><p>Write + enable the systemd user unit (needs enable-linger for boot persistence)</p><p><strong>Usage:</strong> <code>bupha deploy service [OPTIONS]</code></p><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--no-start</code> — Skip enable --now (write the file only)</li></ul><h2 id="bupha-deploy-webhook" tabindex="-1"><code>bupha deploy webhook</code> <a class="header-anchor" href="#bupha-deploy-webhook" aria-label="Permalink to &quot;`bupha deploy webhook`&quot;">​</a></h2><p>Register/update the repo&#39;s push webhook via <code>gh api</code></p><p><strong>Usage:</strong> <code>bupha deploy webhook</code></p><h2 id="bupha-deploy-env" tabindex="-1"><code>bupha deploy env</code> <a class="header-anchor" href="#bupha-deploy-env" aria-label="Permalink to &quot;`bupha deploy env`&quot;">​</a></h2><p>Seed ~/.config/bupha/env with the secret names</p><p><strong>Usage:</strong> <code>bupha deploy env</code></p><h2 id="bupha-deploy-check" tabindex="-1"><code>bupha deploy check</code> <a class="header-anchor" href="#bupha-deploy-check" aria-label="Permalink to &quot;`bupha deploy check`&quot;">​</a></h2><p>Verify the whole install: unit, secrets, hook, endpoint, token</p><p><strong>Usage:</strong> <code>bupha deploy check</code></p><h2 id="bupha-deploy-release" tabindex="-1"><code>bupha deploy release</code> <a class="header-anchor" href="#bupha-deploy-release" aria-label="Permalink to &quot;`bupha deploy release`&quot;">​</a></h2><p>One-time seed: cargo publish in dep order + tag {repo}-v{ver}. Explicit — publishing is the irreversible step in the flow</p><p><strong>Usage:</strong> <code>bupha deploy release [OPTIONS]</code></p><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--dry-run</code> — Print the publish order and tag without doing anything</li></ul><h2 id="bupha-destroy" tabindex="-1"><code>bupha destroy</code> <a class="header-anchor" href="#bupha-destroy" aria-label="Permalink to &quot;`bupha destroy`&quot;">​</a></h2><p>Teardown counterparts of <code>deploy</code></p><p><strong>Usage:</strong> <code>bupha destroy &lt;COMMAND&gt;</code></p><h6 id="subcommands-2" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-2" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>service</code> — Disable + remove the systemd user unit</li><li><code>webhook</code> — Delete the repo&#39;s webhook whose URL matches tunnel.public_url</li><li><code>worktrees</code> — Remove detached worktrees and the persisted queue file</li></ul><h2 id="bupha-destroy-service" tabindex="-1"><code>bupha destroy service</code> <a class="header-anchor" href="#bupha-destroy-service" aria-label="Permalink to &quot;`bupha destroy service`&quot;">​</a></h2><p>Disable + remove the systemd user unit</p><p><strong>Usage:</strong> <code>bupha destroy service</code></p><h2 id="bupha-destroy-webhook" tabindex="-1"><code>bupha destroy webhook</code> <a class="header-anchor" href="#bupha-destroy-webhook" aria-label="Permalink to &quot;`bupha destroy webhook`&quot;">​</a></h2><p>Delete the repo&#39;s webhook whose URL matches tunnel.public_url</p><p><strong>Usage:</strong> <code>bupha destroy webhook</code></p><h2 id="bupha-destroy-worktrees" tabindex="-1"><code>bupha destroy worktrees</code> <a class="header-anchor" href="#bupha-destroy-worktrees" aria-label="Permalink to &quot;`bupha destroy worktrees`&quot;">​</a></h2><p>Remove detached worktrees and the persisted queue file</p><p><strong>Usage:</strong> <code>bupha destroy worktrees</code></p><hr><p><small><i> This document was generated automatically by <a href="https://crates.io/crates/clap-markdown"><code>clap-markdown</code></a>. </i></small></p>',67)])])}const b=o(d,[["render",h]]);export{u as __pageData,b as default};
